cat > spec/book_time.spec.sh <<'EOF'
#!/bin/bash
fail=0
t=$(mktemp); printf '# h\n' > "$t"
# 開始の時刻の形式が違うとき exit 2 で、予約は保存されない
BOOKINGS=$t bash src/book.sh aoi 2026-01-05 9am 10:00 x >/dev/null 2>&1; rc=$?
[ "$rc" = 2 ] || { echo "9am: expected exit 2, got $rc"; fail=1; }
[ "$(grep -vc '^#' "$t")" = 0 ] || { echo "a rejected booking was stored"; fail=1; }
# 終了の時刻の形式が違うとき exit 2 で、予約は保存されない
BOOKINGS=$t bash src/book.sh aoi 2026-01-05 09:00 10am x >/dev/null 2>&1; rc=$?
[ "$rc" = 2 ] || { echo "10am: expected exit 2, got $rc"; fail=1; }
[ "$(grep -vc '^#' "$t")" = 0 ] || { echo "a rejected booking was stored"; fail=1; }
rm -f "$t"; exit $fail
EOF
bash tools/check 2>&1 | tail -3; bash tools/lint 2>&1 | tail -3; echo "lint rc=$?"

